// Include the real .ino handlers (generated by extract_hid_routes.py), with only
// the USB/BLE boundaries replaced. No copied command or route implementation.
#include "route_stubs/Arduino.h"
#include <cassert>
#include <cstdio>
#include <vector>
#include "../hid_bridge/src/hid/transport.h"
#include "../hid_bridge/src/hid/keys.h"
#include "../hid_bridge/src/hid/pace.h"

static int pref = HID_PREF_AUTO;
static bool usbMounted, usbSuspended, bleConnected;
static bool bleButton, bleKey, bleConsumerHeld, usbButton, usbKey, usbConsumer;
static int wakeups, usbMoves;
static bool failBleRelease;
static bool suspendUsbDuringDelay;
static std::vector<std::string> events;
void delay(int) { if (suspendUsbDuringDelay) usbSuspended = true; }
bool tud_mounted() { return usbMounted; }
bool tud_suspended() { return usbSuspended; }
void tud_remote_wakeup() { wakeups++; usbSuspended = false; }
bool ble_hid_connected() { return bleConnected; }
bool ble_hid_bonded() { return bleConnected; }
bool ble_app_advertising() { return true; }
bool ble_hid_pair_window_open() { return false; }
int ble_hid_pref() { return pref; }
void ble_hid_arm_interval(int) {}
bool ble_hid_mouse(int8_t, int8_t, int8_t, int8_t) { return bleConnected; }
bool ble_hid_button(bool down) {
  if (!bleConnected || (!down && failBleRelease)) return false;
  events.push_back(down ? "ble mouse down" : "ble mouse up");
  bleButton = down;
  return true;
}
bool ble_hid_keyboard(uint8_t mod, const uint8_t *, int n) {
  bool down = mod || n;
  if (!bleConnected || (!down && failBleRelease)) return false;
  bleKey = down;
  events.push_back(down ? "ble key down" : "ble key up");
  return true;
}
bool ble_hid_consumer(uint16_t usage) {
  if (!bleConnected || (!usage && failBleRelease)) return false;
  bleConsumerHeld = usage != 0;
  events.push_back(usage ? "ble consumer down" : "ble consumer up");
  return true;
}
struct Mouse {
  void move(int, int, int = 0, int = 0) { usbMoves++; events.push_back("usb move"); }
  void press(int) { usbButton = true; events.push_back("usb mouse down"); }
  void release(int) { if (!usbMounted || usbSuspended) return; usbButton = false; events.push_back("usb mouse up"); }
} mouse;
struct Keyboard {
  void releaseAll() { if (!usbMounted || usbSuspended) return; usbKey = false; events.push_back("usb key up"); }
  void press(int) { usbKey = true; }
  void print(const String &) {}
} keyboard;
struct Consumer {
  void press(int) { usbConsumer = true; }
  size_t release() { if (!usbMounted || usbSuspended) return 0; usbConsumer = false; events.push_back("usb consumer up"); return 1; }
} consumer;
const int HOME_REPORTS = 25, MOUSE_LEFT = 1;
const uint16_t AC_HOME = 0x0223;
enum { KEY_RETURN = 0x80, KEY_ESC, KEY_TAB, KEY_BACKSPACE, KEY_UP_ARROW, KEY_DOWN_ARROW,
       KEY_LEFT_ARROW, KEY_RIGHT_ARROW, KEY_LEFT_GUI, KEY_LEFT_CTRL, KEY_LEFT_ALT, KEY_LEFT_SHIFT };
#include "hid_routes.inc"

static void reset() {
  pref = HID_PREF_AUTO;
  usbMounted = bleConnected = true;
  usbSuspended = false;
  bleButton = bleKey = bleConsumerHeld = usbButton = usbKey = usbConsumer = false;
  failBleRelease = suspendUsbDuringDelay = false;
  wakeups = usbMoves = 0;
  memset(heldReports, 0, sizeof heldReports);
  memset(releasePending, 0, sizeof releasePending);
  events.clear();
}

static void auto_switch_release() {
  reset();
  usbSuspended = true;
  assert(run("press") == "ok" && bleButton);
  usbSuspended = false;
  assert(run("release") == "ok");
  assert(!bleButton && "release after auto BLE->USB must release BLE");
  puts("ok auto switch releases original BLE route");

  reset();
  usbSuspended = true;
  assert(run("press") == "ok");
  usbSuspended = false;
  events.clear();
  assert(run("move 1 0") == "ok");
  assert(events.size() == 2 && events[0] == "ble mouse up" && events[1] == "usb move");
  puts("ok auto switch releases before sending on new route");
}

static void explicit_switch_release() {
  reset();
  pref = HID_PREF_BLE;
  assert(run("press") == "ok" && bleButton);
  assert(hid_prepare_pref(HID_PREF_USB) && !bleButton);
  pref = HID_PREF_USB;  // setter only commits after this real hook succeeds
  assert(run("release") == "ok" && !bleButton);
  puts("ok explicit preference hook releases old route");

  reset();
  pref = HID_PREF_BLE;
  assert(run("press") == "ok");
  failBleRelease = true;
  assert(!hid_prepare_pref(HID_PREF_USB));
  assert(bleButton && heldReports[HID_PATH_BLE] == HELD_MOUSE);
  failBleRelease = false;
  assert(hid_prepare_pref(HID_PREF_USB) && !bleButton);
  puts("ok failed explicit release remains retryable");
}

static void auto_switch_failure() {
  reset();
  usbSuspended = true;
  assert(run("press") == "ok");
  usbSuspended = false;
  failBleRelease = true;
  events.clear();
  assert(run("press") == "err hid release pending");
  assert(run("move 1 0") == "err hid release pending");
  assert(bleButton && !usbButton && usbMoves == 0 && events.empty());
  failBleRelease = false;
  assert(run("move 1 0") == "ok" && !bleButton);
  puts("ok failed auto release blocks new route and recovers");
}

static void emergency_release_all_routes() {
  reset();
  assert(buttonOn(HID_PATH_USB, true));
  assert(buttonOn(HID_PATH_BLE, true));
  uint8_t key = 4;
  assert(bleKeyboard(0, &key, 1));
  assert(bleConsumer(AC_HOME));
  usbSuspended = true;
  pref = HID_PREF_USB;  // selected route unavailable; BLE still needs release
  assert(run("release") == "err hid release pending");
  assert(usbButton && !bleButton && !bleKey && !bleConsumerHeld && wakeups == 0);
  assert(heldReports[HID_PATH_USB] == HELD_MOUSE);
  usbSuspended = false;
  assert(activePath() == HID_PATH_USB && !usbButton); // same periodic retry as loop()
  assert(run("release") == "ok");
  puts("ok emergency release attempts both routes and retries unavailable USB");

  reset();
  assert(buttonOn(HID_PATH_USB, true));
  assert(buttonOn(HID_PATH_BLE, true));
  failBleRelease = true;
  assert(run("release") == "err hid release pending" && !usbButton && bleButton);
  failBleRelease = false;
  assert(run("release") == "ok" && !bleButton);
  puts("ok BLE release failure cannot prevent USB emergency release");
}

static void keyboard_consumer_failures() {
  reset();
  pref = HID_PREF_BLE;
  failBleRelease = true;
  assert(run("key a") == "err phone not connected over ble" && bleKey);
  assert(!hid_prepare_pref(HID_PREF_USB));
  failBleRelease = false;
  assert(hid_prepare_pref(HID_PREF_USB) && !bleKey);
  failBleRelease = true;
  assert(run("type a") == "err partial type" && bleKey);
  failBleRelease = false;
  assert(run("release") == "ok" && !bleKey);
  failBleRelease = true;
  assert(run("homescreen") == "err phone not connected over ble" && bleConsumerHeld);
  failBleRelease = false;
  assert(hid_prepare_pref(HID_PREF_USB) && !bleConsumerHeld);
  puts("ok failed keyboard/consumer ups retain original route until release");

  reset();
  pref = HID_PREF_USB;
  suspendUsbDuringDelay = true;
  assert(run("key a") == "err phone not connected over usb" && usbKey);
  assert(!hid_prepare_pref(HID_PREF_BLE) && usbKey);
  assert(wakeups == 0);
  suspendUsbDuringDelay = usbSuspended = false;
  assert(hid_prepare_pref(HID_PREF_BLE) && !usbKey);
  puts("ok suspended USB key-up remains pending until USB resumes");
}

static void accepted_behaviors() {
  reset();
  usbSuspended = true;
  const char *why = nullptr;
  pref = HID_PREF_BLE;
  assert(phoneReady(&why) && wakeups == 0 && usbSuspended);
  pref = HID_PREF_AUTO;
  assert(phoneReady(&why) && wakeups == 0 && usbSuspended);
  usbMounted = usbSuspended = bleConnected = false;
  assert(!movePaced(12, 4, 10) && usbMoves == 0);
  assert(!slamHome() && usbMoves == 0);
  puts("ok BLE never wakes USB; NONE never sends USB mouse movement");
}

int main() {
  auto_switch_release();
  explicit_switch_release();
  auto_switch_failure();
  emergency_release_all_routes();
  keyboard_consumer_failures();
  accepted_behaviors();
}
